import { PlaneGeometry, Mesh, MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const aspect = 512 / 320;
  const width = 1.6;
  const height = 1.0;

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({
    transparent: false,
    depthWrite: true,
  });

  const mesh = new Mesh(geometry, material);

  // Load the grain texture
  const texturePromise = ctx.textureLoader.loadTexture(
    config.imageUrl || '/prism-assets/chrome/ceramic-grain.map.png'
  );
  texturePromise.then((tex) => {
    // Assume texture is the full atlas region (no offset needed)
    material.map = tex;
    material.needsUpdate = true;
  });

  // Events – none for this static element
  mesh.userData.handlers = {};

  // Cleanup
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texturePromise.then((tex) => tex.dispose());
  };

  return mesh;
}
